create table if not exists public.direct_conversations (conversation_id uuid primary key references public.conversations(id) on delete cascade, user_one uuid not null references public.profiles(id) on delete cascade, user_two uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), unique(user_one,user_two));
create index if not exists direct_conversations_user_one_idx on public.direct_conversations(user_one);
create index if not exists direct_conversations_user_two_idx on public.direct_conversations(user_two);
alter table public.direct_conversations enable row level security;
drop policy if exists "participants view direct conversations" on public.direct_conversations;
create policy "participants view direct conversations" on public.direct_conversations for select to authenticated using (user_one=auth.uid() or user_two=auth.uid());
create or replace function public.get_or_create_direct_conversation(p_username text) returns uuid language plpgsql security definer set search_path=public as $$ declare u uuid:=auth.uid(); target uuid; c uuid; a uuid; b uuid; begin if u is null then raise exception 'not authenticated'; end if; select id into target from public.profiles where username_chosen=true and lower(username)=lower(trim(p_username)); if target is null then raise exception 'User not found.'; end if; if target=u then raise exception 'You cannot message yourself.'; end if; a:=least(u,target); b:=greatest(u,target); select conversation_id into c from public.direct_conversations where user_one=a and user_two=b; if c is not null then return c; end if; insert into public.conversations default values returning id into c; insert into public.conversation_members(conversation_id,user_id) values(c,u),(c,target); insert into public.direct_conversations(conversation_id,user_one,user_two) values(c,a,b); return c; end $$;
revoke all on function public.get_or_create_direct_conversation(text) from public, anon; grant execute on function public.get_or_create_direct_conversation(text) to authenticated;
